package jp.yaegaki.equipment;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;import android.graphics.*;import android.view.View;import java.io.*;import javax.crypto.*;import org.json.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class UiTest {
 @Test public void registrationDetailLabelAndDraft()throws Exception{
 MainActivity a=Robolectric.buildActivity(MainActivity.class).create().start().resume().get();for(android.app.Dialog d:a.dialogs)d.dismiss();a.dialogs.clear();a.deleteDatabase("equipment.db");KeyGenerator kg=KeyGenerator.getInstance("AES");kg.init(256);a.store=new Store(a,kg.generateKey());a.unlocked=true;a.home();a.newDevice();a.inputs.get("name").setText("受付パソコン");a.inputs.get("maker").setText("DELL");a.inputs.get("model").setText("OptiPlex 7020");a.inputs.get("location").setText("1階 受付カウンター");a.inputs.get("ip").setText("192.168.24.10");a.inputs.get("mac").setText("AA:BB:CC:DD:EE:FF");a.inputs.get("url").setText("http://192.168.24.10/");a.inputs.get("password").setText("example-only");a.saveDevice();assertEquals("detail",a.screen);assertEquals(1,a.store.all().size());a.labelPage();assertNotNull(a.labelBitmap);assertFalse(a.labelChecks.get("password").isChecked());assertTrue(a.labelChecks.get("qr").isChecked());snapshot(a,"label-screen.png");a.home();a.newDevice();a.inputs.get("name").setText("下書き機器");a.persistDraft();a.home();assertEquals("下書き機器",a.store.draft().getString("name"));snapshot(a,"home-screen.png");a.store.close();
 }
 void snapshot(MainActivity a,String name)throws Exception {a.root.measure(View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(2400,View.MeasureSpec.EXACTLY));a.root.layout(0,0,1080,2400);Bitmap bmp=Bitmap.createBitmap(1080,2400,Bitmap.Config.ARGB_8888);a.root.draw(new Canvas(bmp));File dir=new File("build/ui-check");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name))){bmp.compress(Bitmap.CompressFormat.PNG,100,out);}}
}
